CREATE OR REPLACE FUNCTION public.catalog_payload_access_allowed(p_user uuid,p_ids text[],p_images text[],p_restricted_reference boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.catalog_source_admin(p_user) OR (NOT coalesce(p_restricted_reference,false) AND NOT EXISTS (SELECT 1 FROM public.catalog_products c WHERE lower(c.source)='aliexpress' AND (c.id::text=ANY(coalesce(p_ids,ARRAY[]::text[])) OR c.external_id=ANY(coalesce(p_ids,ARRAY[]::text[])) OR (jsonb_typeof(c.images)='array' AND c.images ?| coalesce(p_images,ARRAY[]::text[]))))); $$;
REVOKE ALL ON FUNCTION public.catalog_payload_access_allowed(uuid,text[],text[],boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.catalog_payload_access_allowed(uuid,text[],text[],boolean) TO service_role;